-- DAKZO PHASE 5: PREVIEW ONLY / NOT REGISTERED FOR AUTOMATIC EXECUTION
-- Apply ONLY to disposable staging after a security review, never to live ERP.
-- Existing company ownership is NOT changed. No production backfill.
-- All commercial tables FORCE RLS and have NO access policies until the
-- account security boundary is explicitly implemented and independently tested.
--
-- Account identifiers are opaque strings generated by the trusted server.
-- Do not derive identity from company_id, email or client input.

CREATE TABLE IF NOT EXISTS commercial_accounts (
  id VARCHAR(128) PRIMARY KEY,
  name TEXT NOT NULL CHECK (length(trim(name)) > 0),
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','active','suspended','closed')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS commercial_account_companies (
  company_id INTEGER PRIMARY KEY REFERENCES companies(id) ON DELETE RESTRICT,
  account_id VARCHAR(128) NOT NULL REFERENCES commercial_accounts(id) ON DELETE RESTRICT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(account_id,company_id)
);
CREATE INDEX IF NOT EXISTS commercial_account_companies_account_idx
  ON commercial_account_companies(account_id);

CREATE TABLE IF NOT EXISTS commercial_account_members (
  account_id VARCHAR(128) NOT NULL REFERENCES commercial_accounts(id) ON DELETE RESTRICT,
  user_id VARCHAR(255) NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  role TEXT NOT NULL CHECK (role IN ('owner','admin','member','billing')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (account_id,user_id)
);
CREATE INDEX IF NOT EXISTS commercial_account_members_user_idx
  ON commercial_account_members(user_id);

CREATE TABLE IF NOT EXISTS commercial_subscriptions (
  account_id VARCHAR(128) PRIMARY KEY REFERENCES commercial_accounts(id) ON DELETE RESTRICT,
  provider TEXT NOT NULL DEFAULT 'manual' CHECK (provider IN ('manual','paddle','other')),
  provider_subscription_id VARCHAR(160),
  plan TEXT NOT NULL CHECK (plan IN ('retail','business','factory','enterprise')),
  status TEXT NOT NULL DEFAULT 'incomplete'
    CHECK (status IN ('incomplete','trialing','active','past_due','paused','canceled','expired')),
  sequence BIGINT NOT NULL DEFAULT 0 CHECK (sequence >= 0),
  trial_ends_at TIMESTAMPTZ,
  period_ends_at TIMESTAMPTZ,
  canceled_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(provider,provider_subscription_id)
);

CREATE TABLE IF NOT EXISTS commercial_subscription_events (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  provider TEXT NOT NULL,
  provider_event_id VARCHAR(160) NOT NULL,
  account_id VARCHAR(128) NOT NULL REFERENCES commercial_accounts(id) ON DELETE RESTRICT,
  verified_at TIMESTAMPTZ NOT NULL,
  processed_at TIMESTAMPTZ,
  event_status TEXT NOT NULL CHECK (event_status IN ('received','processed','ignored','rejected')),
  event_type TEXT NOT NULL,
  event_hash CHAR(64) NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(provider,provider_event_id)
);
CREATE INDEX IF NOT EXISTS commercial_events_account_idx
  ON commercial_subscription_events(account_id,created_at DESC);

-- Access is denied to ordinary app roles until the commercial account
-- request identity, RLS policies, cross-account negative tests and backend
-- service execution model are designed and approved.
ALTER TABLE commercial_accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE commercial_accounts FORCE ROW LEVEL SECURITY;
ALTER TABLE commercial_account_companies ENABLE ROW LEVEL SECURITY;
ALTER TABLE commercial_account_companies FORCE ROW LEVEL SECURITY;
ALTER TABLE commercial_account_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE commercial_account_members FORCE ROW LEVEL SECURITY;
ALTER TABLE commercial_subscriptions ENABLE ROW LEVEL SECURITY;
ALTER TABLE commercial_subscriptions FORCE ROW LEVEL SECURITY;
ALTER TABLE commercial_subscription_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE commercial_subscription_events FORCE ROW LEVEL SECURITY;
